      "E) Diğer sayfaya geçiniz.\t3  -- 5 of 29 --  2016-KPSS-OÖ/GY Bir kamyon, alnını irili ufaklı, yedi renk farla süslemiş, gösteri yapıyor. Yaktığı farlarla karşıdan gelenlerin gözünü alıyor. Kamyonun giriştiği bu gösteri çabası, Bayram'ı delirtmeye yetiyor. Kamyon, suyla kaplı asfaltta bulanık renkler bırakarak ilerliyor. Yolun sağında ve solunda akıl almaz bir curcunayla kaynaşan her şey tek çizgi hâlinde Bayram'ın gözlerinin iki yanından akıp geçiyor. Bu parçada aşağıdaki anlatım tekniklerinin hangilerinden yararlanılmıştır? Öyküleyici - betimleyici\tAçıklayıcı - kanıtlayıcı Betimleyici - açıklayıcı\tTartışmacı - öyküleyici Kanıtlayıcı - tartışmacı Kadercilik, genel anlamda insanın kendi hayatını kontrol altında tutma ve yönetme çabasına girmeden kendisini olayların akışına bırakması demektir. Kaderciliği kader inancıyla karıştırmamak gerekir. Kadercilik anlayışına göre, insanın başına gelecekler önceden bellidir, olacağa çare yoktur ve yazgı değiştirilemez. Kadere teslim olmak gerekir. O hâlde ----. Bu parçanın sonuna düşüncenin akışına göre aşağıdakilerden hangisi getirilmelidir? herkesin kaderi yalnızca kendisine özgüdür kaderde kişisel iradenin etkisi yoktur hayatın akışı kişinin alacağı kararlara bağlıdır kişinin sorumluluk alması tehlikeli ve risklidir kaderi belirleyen sebepler değil sonuçlardır"
