      "E) Aile, hem kavram hem de kurum olarak insanlık tarihi kadar eskidir. Bir yandan insanlık tarihindeki, diğer yandan toplumların kendi tarihî seyirlerindeki gelişmelere paralel olarak aile kavramının kapsamı değişmiştir. En eski toplumlardan başlayarak yerleşik tarım toplumuna, sonra da ticaret ve sanayi toplumuna gelinceye kadar aile kavramı farklı anlam ve içerikler kazanmıştır. Bu parçaya göre aile kurumuyla ilgili olarak aşağıdakilerden hangisi söylenebilir? Ekonomik dönüşümlerin üzerinde etkili olmuştur. Toplumların biçimlenmesinde belirgin bir rol oynamıştır. Toplumlarda görülen ilerlemelerden etkilenmiştir. Çağdaş toplumlarda, önemi giderek azalmaktadır. Tarihî dönemlerin belirlenmesinde önemli bir ölçüttür. Evinizde balık beslemek isteseydiniz nasıl bir akvaryum seçerdiniz? Basit bir cam fanus mu yoksa donanımlı dev bir akvaryum mu? Göz zevkinize göre yapacağınız seçim, balıklar için yaşamsal öneme sahiptir. Yapılan bir araştırmada, küçük, basit ve donanımsız akvaryumlardaki balıkların daha saldırgan oldukları gözlemlenmiş. Çeşitli nesnelerle donatılmış büyük akvaryumlarda ise balıkların diğer balıklarla kapışmak yerine enerjilerini ortamı keşfetmeye harcadıkları tespit edilmiş. Araştırma bulguları, balıkların kendilerine ait bir alana ihtiyaç duydukları gerçeğini ortaya koymuştur. Dolayısıyla akvaryum alırken bu bilgiye göre seçim yapmanız balıklar açısından büyük önem taşımaktadır. Bu parçada sözü edilen araştırmanın konusu aşağıdakilerden hangisidir? Akvaryum ortamının balıkların davranışlarına etkisi Akvaryum ve balık türü seçiminde insanların tercihi Akvaryum ortamındaki balıkların birbiriyle iletişimi Akvaryum şartlarının balıkların beslenmesine etkisi Akvaryum hacminin balıkların algılama gücüne etkisi"
