      "E) Diğer sayfaya geçiniz.\t5  -- 7 of 29 --  2016-KPSS-OÖ/GY Çocukların gerçek ile hayalî olanı ayırt etme becerisi ileri yaşlarda gelişir. Üç yaş öncesi çocuklar için televizyonda görülen her şey gerçektir; bu yüzden televizyon yana eğilirse ekrandaki bir bardak suyun da döküleceğini zannederler. Üç yaşından sonra ise televizyondaki gerçekliğin yaşamımızdaki gerçeklikten bir ölçüde farklılık gösterdiğini anlamaya başlarlar. Dolayısıyla çocuklar özdeşim kurdukları sanal kahramanlarla yatıp kalkabilir, tıpkı o çizgi kahramanlar gibi olmak isteyebilir, onun gibi kötülerle savaşıp kavga ettikleri bir dünya kurabilir. Ancak çok fazla televizyon izleyen çocuklar, sürekli izledikleri sanal dünyada yaşamaya alışırlarsa, bu farkındalığın gelişimi gecikir ve gerçek hayata uyum sorunları yaşamaya başlarlar. Bunun trajik bir örneği sevdiği çizgi film kahramanı gibi uçacağını zannedip evlerinin üst katından atlayan çocukla ilgili haberdir. Bu trajik olay aynı zamanda bizi, çocukların dünyasını anlamaya ve gerekli önlemleri almaya sevk eden önemli bir uyarıcı olmuştur. Bir şeye atfedilen gerçeklik ne kadar fazla ise ondan etkilenmemiz de o derece fazla olacağından gerçeği ve hayali ayırt edemeyen küçük çocukların televizyondan etkilenmelerinin daha büyük boyutlarda olduğunu görebiliriz. Bu parçada asıl anlatılmak istenen aşağıdakilerden hangisidir? Gerçek ile hayal dünyası arasındaki ilişkiler çocuğun hayatında büyük etkiye sahiptir. Çocukların çizgi filmlere verdiği tepkiler gerçeği algılama süreçlerini de etkiler. Çocukların televizyonu ebeveyn gözetimi altında izlemesi gelişimleri için gereklidir. Televizyon karşısında geçirilen vakit arttıkça, çocuk üzerindeki olumsuz etki artar. Çizgi filmler sayesinde ebeveynin çocuğun hayatı üzerindeki denetimi kolaylaşır. 22. - 23. soruları aşağıdaki parçaya göre cevaplayınız."
