      "E) Diğer sayfaya geçiniz.\t6  -- 8 of 29 --  2016-KPSS-OÖ/GY Bir coğrafyacıya \"Ada nedir?\" diye sorduğunuzda nasıl bir cevap alırsınız? Coğrafi konumu, yüzey şekilleri, yüz ölçümü, nüfusu ve iklimi incelenen, her yanı suyla çevrili olan kara parçasıdır ada onun için. Peki, bir yazar için adanın anlamı nedir? Yazar, öncelikle ada diye tanımlanan yer biçiminin doğal yapısında bulunan birtakım özelliklere, bu özelliklerin kendisine sağlayacağı anlatım imkânlarına ilgi duyar. Mesela bütün adalarda dışarıdan ayrılmış, kendiyle sınırlanmış olma hâli vardır. Her ada, bir bakıma bütünden ayrılmış, dünyayı veya ana karayı uzağında, dışında bırakmıştır. Adada yaşayan bir kimse için dört bir yanını çepeçevre kuşatan denizlerin ötesindeki dünya, \"dışarı\"dır. Ada-dünya ilişkisinde göze çarpan bu içeri-dışarı karşıtlığı bütün adalar için geçerlidir. Çünkü her ada, alabildiğine geniş, sonsuz, karmaşık dış dünya ile karşılaştırıldığında, sınırları belli olan bir yaşama alanıdır. Yazar da ada dendiği zaman kendini bu yaşam alanının içinde bulur. Bu parçada asıl anlatılmak istenen aşağıdakilerden hangisidir? Edebiyatta ada kavramı daha çok soyut nitelikleriyle öne çıkar. Ada, ortak bir tanım üzerinde uzlaşılamayan kavramların başında gelir. Edebiyat ile bilim zaman zaman birbiriyle çelişen kavramlar kullanır. Edebiyat, ele aldığı kavramları okura sunarken gerçeklikten uzaklaştırır. Kavramlara yüklenen anlamlar bakış açısına göre değişkenlik gösterir. 24. - 26. soruları aşağıdaki parçaya göre cevaplayınız."
